<section class="admin-panel"><div class="panel-head"><h2>Animales registrados <small>(<?= count($rows) ?> resultados recientes)</small></h2><label class="mini-search">⌕ <input type="search" data-filter-table placeholder="Buscar en esta lista..." aria-label="Buscar animales en esta lista"></label></div><div class="table-scroll"><table class="data-table" data-table><thead><tr><th>Animal</th><th>Especie</th><th>Salud</th><th>Adopción</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $a):?><tr><td><div class="animal-col"><img src="<?= e(asset($a['foto'])) ?>" loading="lazy" alt=""><span><strong><?= e($a['nombre']) ?></strong><small>#<?= (int)$a['id'] ?></small></span></div></td><td><?= e($a['especie']) ?></td><td><span class="chip chip-neutral"><?= e(str_replace('_',' ',$a['estado_salud'])) ?></span></td><td><span class="chip chip-soft"><?= e(str_replace('_',' ',$a['estado_adopcion'])) ?></span></td><td><?= (int)$a['archivado']===1?'Archivado':'Activo' ?></td><td><a class="table-link" href="/admin/animales/<?= (int)$a['id'] ?>/editar">Editar ↗</a></td></tr><?php endforeach ?></tbody></table></div><?php if(!$rows): ?><div class="empty">No hay animales registrados.</div><?php endif ?></section>
